{"cards": [{"node_code": "N_f8b1b292c25cd74d", "definition": "涵盖用于立体仓库中货物垂直升降、水平行走及自动存取作业的专用机械装备，包括单/双立柱堆垛机、多层穿梭车及自动存取系统（AS/RS）。", "boundary": "聚焦于固定轨道或巷道内的垂直/水平存取作业。与“AGV/AMR”的区别在于本节点设备通常依赖固定轨道或巷道结构，侧重高精度定位与货架交互；与“分拣输送”的区别在于本节点侧重存储与提取，而非高速分拣或连续输送。", "includes": ["单立柱、双立柱及多立柱堆垛机的结构、控制与性能", "多层穿梭车、子母车及巷道内水平搬运设备", "自动存取系统（AS/RS）的集成、调度逻辑及货架接口"], "excludes": ["无固定轨道、基于SLAM或激光导航的自主移动机器人（归入AGV、AMR与移动搬运机器人）", "用于高速分拣、拆码垛或长距离连续输送的流水线设备（归入分拣、拆码垛与输送系统）"], "sibling_distinctions": [{"other_code": "N_c14d9eb8a8a2e280", "rule": "本节点收录依赖固定轨道/巷道的存取设备（如堆垛机）；兄弟节点收录无固定轨道、具备自主导航能力的移动搬运机器人。"}, {"other_code": "N_2e94bcaed6ce6c0c", "rule": "本节点侧重货物的存储与提取（存取）；兄弟节点侧重货物的分类、堆叠/拆解及连续输送过程。"}], "cross_boundary_rule": "涉及穿梭车时，若其在固定巷道内运行且主要配合堆垛机进行存取，主挂载至本节点；若其具备自主路径规划能力并在开放区域移动，可次关联至AGV/AMR节点。"}, {"node_code": "N_c14d9eb8a8a2e280", "definition": "涵盖在仓储环境中用于货物水平移动搬运的自动导引车（AGV）及自主移动机器人（AMR），包括其导航、调度及与物流系统的集成。", "boundary": "聚焦于无固定轨道或基于磁钉/二维码/SLAM导航的移动搬运单元。与“堆垛机”的区别在于本节点设备具备自主移动能力，不依赖固定巷道结构；与“分拣输送”的区别在于本节点侧重点对点或路径式搬运，而非连续流分拣。", "includes": ["自动导引车（AGV）的导航技术、底盘结构及驱动系统", "自主移动机器人（AMR）的感知、避障及路径规划算法", "移动搬运机器人的调度系统、WMS集成及人机协作安全"], "excludes": ["依赖固定轨道运行的堆垛机或穿梭车（归入堆垛机、穿梭车与自动存取系统）", "用于高速分拣、拆码垛或连续输送的固定式流水线设备（归入分拣、拆码垛与输送系统）"], "sibling_distinctions": [{"other_code": "N_f8b1b292c25cd74d", "rule": "本节点收录具备自主导航能力的移动机器人；兄弟节点收录依赖固定轨道/巷道的存取设备。"}, {"other_code": "N_2e94bcaed6ce6c0c", "rule": "本节点侧重移动搬运单元；兄弟节点侧重固定式或连续式的分拣、拆码垛及输送线。"}], "cross_boundary_rule": "涉及移动机器人时，若研究其在仓储场景下的调度、任务分配及与WMS集成，主挂载至本节点；若研究其通用底盘、驱动电机或基础导航算法，可次关联至通用机器人技术或工业车辆节点。"}, {"node_code": "N_2e94bcaed6ce6c0c", "definition": "涵盖用于货物自动分类、堆叠/拆解及连续输送的自动化物流装备与系统，包括分拣机、拆码垛机器人及各类输送线。", "boundary": "聚焦于单元化货物的处理流程，包括识别、分拣、堆垛/拆垛及连续输送。与“堆垛机”的区别在于本节点侧重处理与流转，而非存储；与“AGV/AMR”的区别在于本节点设备多为固定式或连续式，而非独立移动单元。", "includes": ["交叉带、滑块、摆轮等自动分拣系统及视觉识别技术", "拆码垛机器人、机械臂及托盘堆叠/拆解设备", "辊道、皮带、链式等连续输送线及缓冲、合流设备"], "excludes": ["用于散料（如煤炭、粮食）的连续输送与处理机械（归入连续输送与散料处理机械）", "用于垂直起吊重物的起重机、葫芦及卷扬机（归入起重机械）"], "sibling_distinctions": [{"other_code": "N_f8b1b292c25cd74d", "rule": "本节点侧重货物的分拣、拆码垛及连续输送；兄弟节点侧重货物的存储与提取（存取）。"}, {"other_code": "N_c14d9eb8a8a2e280", "rule": "本节点侧重固定式或连续式的处理与输送设备；兄弟节点侧重独立移动搬运的机器人单元。"}], "cross_boundary_rule": "涉及输送线时，若研究其作为分拣/拆码垛系统的组成部分，主挂载至本节点；若研究其通用输送原理或散料输送，可次关联至连续输送与散料处理机械节点。"}]}
